const $v3=id=>document.getElementById(id)||DOM_STUB;
function cloneQ(q){return JSON.parse(JSON.stringify(q))}
function uniqueById(arr){const m=new Map();arr.forEach(q=>q&&m.set(q.id,q));return [...m.values()]}
function uniqueByContent(arr){const m=new Map();arr.forEach(q=>{if(!q)return;const key=(q.section||'')+'|'+(q.passage||'')+'|'+(q.q||'')+'|'+JSON.stringify(q.choices||[])+'|'+q.a;if(!m.has(key))m.set(key,q);});return [...m.values()]}
function pct(c,t){return t?Math.round(c/t*100):0}

