function v17Fill(exam,target,maker){let i=0,guard=0;while(PRO_BANK[exam].length<target&&guard<target*5){const q=maker(i++);if(q&&!PRO_BANK[exam].some(x=>x.id===q.id))PRO_BANK[exam].push(q);guard++}}
v17Fill('SAT',V17_TARGETS.SAT,v17SATOne);v17Fill('ACT',V17_TARGETS.ACT,v17ACTOne);v17Fill('TSIA2',V17_TARGETS.TSIA2,v17TSIOne);
function v17BalanceAnswerPositions(bank){
  bank.forEach((q,idx)=>{
    if(!q||!Array.isArray(q.choices)||q.choices.length!==4||!Array.isArray(q.why)||q.why.length!==4)return;
    const shift=idx%4;
    if(!shift)return;
    const items=q.choices.map((choice,i)=>({choice,why:q.why[i],correct:i===q.a}));
    const rotated=items.slice(-shift).concat(items.slice(0,-shift));
    q.choices=rotated.map(x=>x.choice);q.why=rotated.map(x=>x.why);q.a=rotated.findIndex(x=>x.correct);
  });
}
v17BalanceAnswerPositions(PRO_BANK.SAT);v17BalanceAnswerPositions(PRO_BANK.ACT);v17BalanceAnswerPositions(PRO_BANK.TSIA2);

function v17QualityAudit(bank,exam){const issues=[];const ids=new Set();for(const q of bank){if(!q||!q.id||ids.has(q.id)){issues.push([q?.id,'duplicate/missing id']);continue}ids.add(q.id);if(!q.section||!q.skill||!['Easy','Medium','Hard'].includes(q.difficulty))issues.push([q.id,'metadata']);if(!q.q||!Array.isArray(q.choices)||q.choices.length!==4||new Set(q.choices.map(String)).size!==4)issues.push([q.id,'choices']);if(!Number.isInteger(q.a)||q.a<0||q.a>3)issues.push([q.id,'answer']);if(!q.ex||q.ex.length<12)issues.push([q.id,'explanation']);if(!Array.isArray(q.why)||q.why.length!==4||q.why.some(x=>!x||x.length<3))issues.push([q.id,'why']);if(!q.strategy||q.strategy.length<8)issues.push([q.id,'strategy']);}return issues}
const V17_AUDIT={SAT:v17QualityAudit(PRO_BANK.SAT,'SAT'),ACT:v17QualityAudit(PRO_BANK.ACT,'ACT'),TSIA2:v17QualityAudit(PRO_BANK.TSIA2,'TSIA2')};
window.SCOREPATH_V17_BANK_REPORT={targets:V17_TARGETS,counts:{SAT:PRO_BANK.SAT.length,ACT:PRO_BANK.ACT.length,TSIA2:PRO_BANK.TSIA2.length,total:PRO_BANK.SAT.length+PRO_BANK.ACT.length+PRO_BANK.TSIA2.length},structuralIssues:{SAT:V17_AUDIT.SAT.length,ACT:V17_AUDIT.ACT.length,TSIA2:V17_AUDIT.TSIA2.length},note:'Original blueprint-aligned practice. Correct-answer positions are balanced in the bank and randomized again per student session. No previously administered official question is copied or lightly edited.'};
spConsole('info','ScorePath V17 5K bank',window.SCOREPATH_V17_BANK_REPORT);


/* ---------- V6: official-blueprint alignment + new high-fidelity ORIGINAL practice ---------- */
const SCOREPATH_BLUEPRINT={
 SAT:{
  sections:['Reading & Writing','Math'],
  domains:['Information & Ideas','Craft & Structure','Expression of Ideas','Standard English Conventions','Algebra','Advanced Math','Problem-Solving & Data Analysis','Geometry & Trigonometry']
 },
 ACT:{
  sections:['English','Math','Reading','Science (Optional)'],
  domains:['Production of Writing','Knowledge of Language','Conventions of Standard English','Number & Quantity','Algebra','Functions','Geometry','Statistics & Probability','Integrating Essential Skills','Modeling','Key Ideas & Details','Craft & Structure','Integration of Knowledge & Ideas','Interpretation of Data','Scientific Investigation','Evaluating Scientific Arguments and Models with Evidence']
 },
 TSIA2:{
  sections:['Mathematics','ELAR'],
  domains:['Quantitative Reasoning','Algebraic Reasoning','Geometric and Spatial Reasoning','Probabilistic and Statistical Reasoning','Literary Text Analysis','Informational Text Analysis and Synthesis','Essay Revision and Editing','Sentence Revision, Editing, and Completion']
 }
};
function blueprintDomain(exam,q){
 const s=q.skill||'',sec=q.section||'';
 if(exam==='SAT') return SCOREPATH_BLUEPRINT.SAT.domains.includes(s)?s:null;
 if(exam==='ACT'){
  if(sec==='English'){
   if(/Organization|Rhetoric|Production/i.test(s))return 'Production of Writing';
   if(/Language|Style|Conciseness|Word Choice/i.test(s))return 'Knowledge of Language';
   if(/Grammar|Usage|Punctuation|Conventions/i.test(s))return 'Conventions of Standard English';
  }
  if(sec==='Math'){
   if(/Number|Quantity/i.test(s))return 'Number & Quantity';
   if(/Algebra/i.test(s))return 'Algebra';
   if(/Function/i.test(s))return 'Functions';
   if(/Geometry|Trig/i.test(s))return 'Geometry';
   if(/Statistic|Probability/i.test(s))return 'Statistics & Probability';
   if(/Integrating|Essential/i.test(s))return 'Integrating Essential Skills';
   if(/Model/i.test(s))return 'Modeling';
  }
  if(sec==='Reading'){
   if(/Main Idea|Inference|Key Ideas|Detail/i.test(s))return 'Key Ideas & Details';
   if(/Craft|Structure|Vocabulary|Author/i.test(s))return 'Craft & Structure';
   if(/Integration|Knowledge|Evidence/i.test(s))return 'Integration of Knowledge & Ideas';
  }
  if(sec==='Science (Optional)'){
   if(/Data|Interpret/i.test(s))return 'Interpretation of Data';
   if(/Experiment|Investigation|Design/i.test(s))return 'Scientific Investigation';
   if(/Model|Inference|Argument|Evidence/i.test(s))return 'Evaluating Scientific Arguments and Models with Evidence';
  }
  return null;
 }
 if(exam==='TSIA2'){
  if(sec==='Mathematics'){
   if(/Quantitative/i.test(s))return 'Quantitative Reasoning';
   if(/Algebraic/i.test(s))return 'Algebraic Reasoning';
   if(/Geometric|Spatial/i.test(s))return 'Geometric and Spatial Reasoning';
   if(/Probabilistic|Statistical/i.test(s))return 'Probabilistic and Statistical Reasoning';
  }
  if(sec==='ELAR'){
   if(/Literary/i.test(s))return 'Literary Text Analysis';
   if(/Main Idea|Inference|Vocabulary|Author|Informational/i.test(s))return 'Informational Text Analysis and Synthesis';
   if(/Revision|Organization/i.test(s))return 'Essay Revision and Editing';
   if(/Sentence|Grammar|Usage|Editing|Transition/i.test(s))return 'Sentence Revision, Editing, and Completion';
  }
  return null;
 }
 return null;
}
function validatePracticeItem(exam,q){
 const bp=SCOREPATH_BLUEPRINT[exam];
 if(!q||!bp||!bp.sections.includes(q.section))return false;
 if(!Array.isArray(q.choices)||q.choices.length!==4||!Number.isInteger(q.a)||q.a<0||q.a>3)return false;
 if(!q.q||!q.ex||!Array.isArray(q.why)||q.why.length!==4||!q.strategy)return false;
 const d=blueprintDomain(exam,q);if(!d)return false;
 q.blueprintDomain=d;q.contentOrigin='ScorePath original — official-blueprint aligned';q.blueprintVerified=true;
 return true;
}
function O(id,section,skill,difficulty,q,choices,a,ex,why,strategy,extra={}){return {id,section,skill,difficulty,q,choices,a,ex,why,strategy,...extra}}

