function launchACTFullStage(){const cfg=actStageConfig(actFull.stage),pool=PRO_BANK.ACT.filter(q=>q.section===cfg.section),set=adaptivePick(pool,cfg.count,'mixed',new Set(),'ACT',cfg.section);if(set.length<cfg.count){alert(`The ACT bank needs ${cfg.count} unique ${cfg.section} questions; only ${set.length} are available.`);actFull.active=false;return}cacheSet(actStore,set);saveACT();actHideAll();$v3('actFullBreak')?.classList.remove('show');$v3('actPracticeShell').classList.add('show');actState={set,i:0,answers:{},confidence:{},flags:[],timed:true,start:Date.now(),seconds:cfg.duration,timerId:null,mode:`act-full-${cfg.section.toLowerCase()}`,submitted:{},duration:cfg.duration,sessionCode:sessionCode('ACT')};$v3('actTestTitle').textContent=`ACT Core Simulation — ${cfg.name}`;$v3('actModeLabel').textContent=`Full Core Simulation • Section ${actFull.stage+1} of 3`;$v3('actConfidenceBox')?.classList.add('hidden');$v3('actSubmitBtn').classList.add('hidden');beginPacing('act',actState,'actTimer',finishACT,cfg.duration);renderACT();location.hash='act-center'}
