const V9_SAT=[],V9_ACT=[],V9_TSI=[];
// SAT: mathematically verified template items.
for(let i=1;i<=12;i++){const x=2+(i%8),a=2+(i%5),b=3+(i%7),c=a*x+b;V9_SAT.push(O(`SAT-V9-ALG-${i}`,'Math','Algebra',i%2?'Medium':'Easy',`If ${a}x + ${b} = ${c}, what is the value of x?`,[String(x),String(x+2),String(c-b),String(Math.max(1,x-1))],0,`Subtract ${b}: ${a}x=${c-b}. Divide by ${a}: x=${x}.`,['Correct solution.','Too large after an extra addition.','This is the value of '+a+'x before division.','This does not satisfy the equation.'],'Isolate x with inverse operations.',{calculatorAllowed:true}))}
for(let i=1;i<=8;i++){const x=2+(i%6),k=1+(i%5),v=x*x+k*x;V9_SAT.push(O(`SAT-V9-ADV-${i}`,'Math','Advanced Math',i%2?'Medium':'Hard',`For f(x)=x²+${k}x, what is f(${x})?`,[String(v),String(v+k),String(x*x+k),String(x+k)],0,`Substitute ${x}: ${x}²+${k}(${x})=${x*x}+${k*x}=${v}.`,['Correct substitution and evaluation.','Adds the coefficient one extra time.','Uses k instead of kx.','Does not evaluate the quadratic term.'],'Substitute first, then use order of operations.',{calculatorAllowed:true}))}
for(let i=1;i<=6;i++){const total=80+i*10,pctv=20+(i%4)*10,part=total*pctv/100;V9_SAT.push(O(`SAT-V9-PSDA-${i}`,'Math','Problem-Solving & Data Analysis','Medium',`A group has ${total} members. ${pctv}% completed a survey. How many members completed it?`,[String(part),String(part+10),String(Math.max(0,part-10)),String(total)],0,`${pctv}% of ${total} is ${pctv/100}×${total}=${part}.`,['Correct percentage of the whole.','This is the number who did not complete it.','This confuses a percent with a count.','This uses division instead of percent multiplication.'],'Convert the percent to a decimal and multiply by the whole.',{calculatorAllowed:true}))}
for(let i=1;i<=6;i++){const r=3+(i%6),area=r*r;V9_SAT.push(O(`SAT-V9-GEO-${i}`,'Math','Geometry & Trigonometry',i%2?'Easy':'Medium',`A circle has radius ${r}. What is its area?`,[`${area}π`,`${2*r}π`,`${r}π`,`${2*area}π`],0,`Area=πr²=π(${r})²=${area}π.`,['Correct area.','This resembles circumference.','This omits the square.','This doubles the area.'],'Use A=πr².',{calculatorAllowed:true}))}
const satTransitions=[['The first trial produced unstable measurements.','the team recalibrated the sensor before trying again.','Therefore'],['The material is lightweight.','it remains strong under repeated stress.','Moreover'],['The route is shorter.','it includes a steep climb near the end.','However'],['The city added shaded benches.','more visitors remained in the plaza during hot afternoons.','As a result']];
for(let i=1;i<=8;i++){const t=satTransitions[(i-1)%satTransitions.length];V9_SAT.push(O(`SAT-V9-EOI-${i}`,'Reading & Writing','Expression of Ideas',i%2?'Medium':'Hard',`${t[0]} _____, ${t[1].charAt(0).toLowerCase()+t[1].slice(1)}`,['For example',t[2],'Instead','Likewise'],1,`“${t[2]}” expresses the required relationship between the ideas.`,['Introduces an example rather than the intended relationship.','Correct transition.','Signals replacement.','Signals similarity.'],'Identify the relationship before choosing a transition.'))}
const satSubjects=['collection','series','group','set','committee','catalog'];
for(let i=1;i<=8;i++){const s=satSubjects[(i-1)%satSubjects.length];V9_SAT.push(O(`SAT-V9-SEC-${i}`,'Reading & Writing','Standard English Conventions',i%3===0?'Medium':'Easy',`Which choice completes the sentence correctly? “The ${s} of research notes _____ stored in a secure archive.”`,['are','were','is','have been'],2,`The grammatical subject “${s}” is singular, so “is” is correct.`,['Plural agreement.','Plural past-tense agreement.','Correct singular agreement.','Plural verb phrase.'],'Find the true subject, not the nearest plural noun.'))}

// ACT English + Math templates.
for(let i=1;i<=14;i++){const n=2+(i%7);V9_ACT.push(O(`ACT-V9-ENG-${i}`,'English',i%2?'Conventions of Standard English':'Knowledge of Language',i%3===0?'Hard':'Medium',i%2?`Choose the correct revision: “Each of the ${n} proposals have a clear purpose.”`:`Choose the most concise revision: “At this point in time, the committee is currently reviewing the proposal.”`,i%2?['Each of the proposals has a clear purpose.','Each of the proposals have a clear purpose.','Each of the proposals having a clear purpose.','Each of the proposals were having a clear purpose.']:['The committee is reviewing the proposal.','At this point, the committee is currently reviewing the proposal.','Currently, at this point in time, the committee is reviewing the proposal.','The committee is now currently reviewing the proposal at this point.'],0,i%2?'“Each” is singular, so “has” is required.':'The first choice removes redundant time expressions without changing meaning.',['Correct.','Agreement or concision error.','Fragment or wordiness problem.','Agreement or wordiness problem.'],'Check agreement and remove unnecessary repetition.'))}
for(let i=1;i<=14;i++){const x=3+(i%8),a=2+(i%4),c=a*x;V9_ACT.push(O(`ACT-V9-MATH-${i}`,'Math',i%4===0?'Geometry':i%3===0?'Functions':'Algebra',i%3===0?'Easy':'Medium',i%4===0?`A rectangle has length ${x+4} and width ${x}. What is its area?`:`If ${a}x=${c}, what is x?`,i%4===0?[String((x+4)*x),String(2*(x+4+x)),String(x*x),String(x+4+x)]:[String(x),String(c),String(x+a),String(Math.max(1,x-2))],0,i%4===0?`Area=length×width=${x+4}×${x}=${(x+4)*x}.`:`Divide both sides by ${a}: x=${x}.`,['Correct.','Uses the wrong operation.','Does not use both required dimensions/steps.','Does not satisfy the problem.'],'Translate the relationship into the correct operation.',{calculatorAllowed:true}))}
const actPassages=[
{txt:'A neighborhood library began lending mobile hotspots after a survey showed that some students lacked reliable internet at home. During the first semester, the devices were checked out almost every day, and the library added evening technology-help sessions.',main:'The library expanded services in response to a documented access need.',detail:'The hotspots were checked out almost every day.',infer:'Demand for internet-access support remained high after the lending program began.',purpose:'To describe how a library responded to an access problem and what happened next.'},
{txt:'A school replaced disposable cafeteria trays with reusable ones. Staff tracked waste for eight weeks and found a substantial drop in trash volume, although dishwashing use increased.',main:'The tray change reduced trash but increased another resource use.',detail:'Staff tracked waste for eight weeks.',infer:'Evaluating an environmental change can require considering more than one resource.',purpose:'To explain two measured effects of replacing disposable trays.'},
{txt:'A city installed curb extensions at several busy intersections. Pedestrians had a shorter distance to cross, and drivers approached the intersections more slowly during follow-up observations.',main:'The street design change was associated with conditions that may improve pedestrian safety.',detail:'Pedestrians had a shorter distance to cross.',infer:'Street design can influence both pedestrian exposure and driver behavior.',purpose:'To describe a street-design change and its observed effects.'}];
actPassages.forEach((p,j)=>{
 V9_ACT.push(O(`ACT-V9-READ-${j+1}-1`,'Reading','Key Ideas & Details','Medium','Which choice best states the main idea of the passage?',[p.main,'The passage proves the same result will occur in every city.','The project was immediately abandoned.','The passage focuses mainly on a personal disagreement.'],0,p.main,['Correct central idea.','Overgeneralizes beyond the evidence.','Contradicted by the passage.','Not the passage focus.'],'Identify the central idea that covers the major evidence.',{passage:p.txt}));
 V9_ACT.push(O(`ACT-V9-READ-${j+1}-2`,'Reading','Key Ideas & Details','Hard','Which inference is most strongly supported by the passage?',[p.infer,'The project had no observable effect.','Every participant had exactly the same experience.','The passage guarantees the result in all future cases.'],0,p.infer,['Best-supported inference.','Contradicted by reported observations.','Not stated or supported.','Too absolute.'],'An inference must be supported without becoming an absolute claim.',{passage:p.txt}));
 V9_ACT.push(O(`ACT-V9-READ-${j+1}-3`,'Reading','Key Ideas & Details','Easy','Which detail is explicitly stated in the passage?',[p.detail,'The project received a national award.','Every resident participated.','The program cost nothing to operate.'],0,p.detail,['Explicitly stated.','Not stated.','Not stated.','Not stated.'],'Return to the passage and match the wording to direct evidence.',{passage:p.txt}));
 V9_ACT.push(O(`ACT-V9-READ-${j+1}-4`,'Reading','Craft & Structure','Medium','Which choice best describes the purpose of the passage?',[p.purpose,'To argue that all communities must adopt the same program.','To criticize a person involved in the project.','To provide step-by-step technical instructions.'],0,p.purpose,['Correct purpose.','The passage does not make a universal demand.','No personal criticism is central.','The passage is not a procedure manual.'],'Ask what the author is mainly doing: describing, explaining, arguing, or comparing.',{passage:p.txt}));
});
const scienceSets=[
{txt:'Researchers tested seed germination at 10°C, 20°C, and 30°C. After seven days, 42%, 78%, and 61% of seeds had germinated, respectively.',best:'20°C',result:'Germination differed across the tested temperatures.',consistent:'The 20°C group had a higher germination percentage than both the 10°C and 30°C groups.'},
{txt:'Three filters removed 35%, 62%, and 81% of suspended particles from equal water samples.',best:'the third filter',result:'Particle removal differed among the three filters.',consistent:'The third filter removed more suspended particles than the first or second filter.'},
{txt:'A battery powered a device for 4.2, 5.7, and 6.1 hours at three tested settings.',best:'the third setting',result:'Operating time varied across the tested settings.',consistent:'The third setting produced the longest measured operating time.'}];
scienceSets.forEach((s,j)=>{
 V9_ACT.push(O(`ACT-V9-SCI-${j+1}-1`,'Science (Optional)','Interpretation of Data','Medium','Which condition produced the largest measured result?',[s.best,'the first tested condition','all conditions produced equal results','the passage reports no measurements'],0,`${s.best} had the largest reported value.`,['Correct comparison.','Not the largest value.','The values differ.','Measurements are provided.'],'Compare the reported values directly.',{passage:s.txt}));
 V9_ACT.push(O(`ACT-V9-SCI-${j+1}-2`,'Science (Optional)','Interpretation of Data','Medium','Which conclusion is best supported by the data?',[s.result,'The same pattern is guaranteed under every untested condition.','The experiment proves that no other variable can matter.','The measurements were identical across all conditions.'],0,s.result,['Correct cautious conclusion.','Too broad.','The data do not eliminate all other variables.','The measurements differ.'],'State only what the measured data support.',{passage:s.txt}));
 V9_ACT.push(O(`ACT-V9-SCI-${j+1}-3`,'Science (Optional)','Scientific Investigation','Hard','Which additional trial would best test whether the observed pattern is repeatable?',['Repeat the same procedure with new samples while holding the tested conditions constant.','Change several variables at once and do not record them.','Use only one condition and one sample.','Replace the measurement method with an unrelated observation.'],0,'Repeating the controlled procedure with new samples tests reproducibility.',['Correct controlled replication.','Too many variables change.','A single condition cannot test the pattern.','An unrelated measure does not test repeatability.'],'Repeat the investigation while controlling variables.',{passage:s.txt}));
 V9_ACT.push(O(`ACT-V9-SCI-${j+1}-4`,'Science (Optional)','Evaluating Scientific Arguments and Models with Evidence','Hard','Which statement is most consistent with the results?',[s.consistent,'The lowest measured result was actually the highest.','All tested conditions produced exactly the same outcome.','No comparison among conditions is possible.'],0,s.consistent,['Matches the reported measurements.','Reverses the data.','Contradicted by differing values.','The values can be compared.'],'Match the claim precisely to the data.',{passage:s.txt}));
});

// TSIA2 Math + ELAR templates.
for(let i=1;i<=20;i++){const w=Math.floor((i-1)/4),x=2+w%8,kind=i%4;let q;if(kind===0){const p=20+w*5,total=100+i*5,ans=total*p/100;q=O(`TSIA2-V9-M-${i}`,'Mathematics','Quantitative Reasoning','Medium',`What is ${p}% of ${total}?`,[String(ans),String(total-p),String(p),String(total)],0,`Convert ${p}% to ${p/100} and multiply by ${total}: ${p/100}×${total}=${ans}.`,['Correct.','Subtracts instead of finding a percent.','Uses the percent as the count.','Uses the whole.'],'Convert percent to decimal and multiply.',{calculatorAllowed:true})}else if(kind===1){const a=2+w%5,b=3+w%4,c=a*x+b;q=O(`TSIA2-V9-M-${i}`,'Mathematics','Algebraic Reasoning',w%3===0?'Easy':'Medium',`Solve: ${a}x+${b}=${c}.`,[String(x),String(x+1),String(x-1),String(c)],0,`Subtract ${b}, then divide by ${a}: x=${x}.`,['Correct.','Does not satisfy the equation.','Stops before dividing.','Uses the constant instead of solving.'],'Use inverse operations.',{calculatorAllowed:true})}else if(kind===2){const l=x+5,ww=x,ans=l*ww;q=O(`TSIA2-V9-M-${i}`,'Mathematics','Geometric and Spatial Reasoning','Medium',`A rectangle measures ${l} by ${ww}. What is its area?`,[String(ans),String(2*(l+ww)),String(l+ww),String(l*l)],0,`Area=${l}×${ww}=${ans}.`,['Correct.','This is perimeter.','This adds dimensions only.','This squares only one dimension.'],'Area of a rectangle is length×width.',{calculatorAllowed:true})}else{const vals=[x,x+1,x+1,x+3,x+5],median=x+1;q=O(`TSIA2-V9-M-${i}`,'Mathematics','Probabilistic and Statistical Reasoning','Medium',`What is the median of ${vals.join(', ')}?`,[String(median),String(x),String(x+3),String(x+5)],0,`The ordered middle value is ${median}.`,['Correct.','This is below the middle.','This is above the middle.','This is the maximum.'],'Order the values and choose the middle observation.',{calculatorAllowed:true})}V9_TSI.push(q)}
const tsiTexts=[
{txt:'A college extended tutoring hours from two evenings to four. Attendance rose during the next term, and students using tutoring completed courses at a higher rate than before.',main:'Expanded tutoring access was associated with increased use and improved completion among participants.',infer:'Making tutoring available on more evenings may have reduced a scheduling barrier for some students.'},
{txt:'A community planted native grasses beside a creek. After heavy rain, the restored bank showed less erosion than an untreated section nearby.',main:'The restoration was associated with reduced erosion.',infer:'Native vegetation may help stabilize soil along a creek bank.'},
{txt:'A museum replaced several technical labels with shorter plain-language versions. Visitors spent more time discussing the exhibits during observations.',main:'Clearer exhibit text was associated with greater visitor engagement.',infer:'How information is presented can influence how visitors interact with exhibits.'}];
for(let i=1;i<=20;i++){const kind=i%4,t=tsiTexts[(i-1)%tsiTexts.length];if(kind===0)V9_TSI.push(O(`TSIA2-V9-E-${i}`,'ELAR','Informational Text Analysis and Synthesis','Medium','Which choice best states the main idea?',[t.main,'The passage proves the same outcome will always occur.','The project was abandoned before completion.','The passage is mainly about an unrelated event.'],0,t.main,['Correct, appropriately qualified main idea.','Too absolute.','Unsupported.','Not the focus.'],'Choose the central claim without making it stronger than the evidence.',{passage:t.txt}));else if(kind===1)V9_TSI.push(O(`TSIA2-V9-E-${i}`,'ELAR','Sentence Revision, Editing, and Completion','Medium','Choose the grammatically correct sentence.',['Each of the reports includes a conclusion.','Each of the reports include a conclusion.','Each of the reports including a conclusion.','Each of the reports have a conclusion yesterday.'],0,'“Each” is singular, so “includes” is correct.',['Correct.','Subject-verb disagreement.','Fragment.','Agreement and tense problem.'],'Find the true subject before choosing the verb.'));else if(kind===2)V9_TSI.push(O(`TSIA2-V9-E-${i}`,'ELAR','Essay Revision and Editing','Medium','A paragraph argues that clearly marked recycling bins increase correct recycling. Which evidence best supports the claim?',['A campus audit found 24% fewer sorting errors in buildings with clearly marked bins.','Some bins are blue.','The campus contains several buildings.','Students sometimes carry water bottles.'],0,'The audit directly measures the outcome named in the claim.',['Direct quantitative evidence.','Color alone does not show effectiveness.','Number of buildings is irrelevant.','Only indirectly related.'],'Choose evidence that directly measures the claim.'));else V9_TSI.push(O(`TSIA2-V9-E-${i}`,'ELAR','Informational Text Analysis and Synthesis','Hard','Which inference is most strongly supported by the passage?',[t.infer,'The same result is guaranteed in every location.','No one benefited from the change.','The passage provides no evidence at all.'],0,t.infer,['Best-supported inference.','Overgeneralizes.','Contradicted or unsupported.','The passage gives evidence.'],'Select an inference supported by the passage without going beyond it.',{passage:t.txt}))}
/* ---------- V20: expanded TSI Math + Reading (curated, verified-correct, original) ---------- */
const v20StartIdx=V9_TSI.length;

// Percent
for(let i=1;i<=10;i++){const cost=15+i*6,p=10+(i%8)*5,price=Math.round(cost*(1-p/100)*100)/100,off=Math.round(cost*p/100*100)/100,added=Math.round(cost*(1+p/100)*100)/100;
V9_TSI.push(O(`TSIA2-V20-M-PCT-${i}`,'Mathematics','Quantitative Reasoning — Percent',i%3===0?'Easy':'Medium',`An item costs $${cost} and is discounted ${p}%. What is the sale price before tax?`,[`$${price}`,`$${off}`,`$${added}`,`$${cost}`],0,`Convert ${p}% to a decimal (${p/100}) and multiply by $${cost} to find the discount, then subtract from the original price: $${cost} − $${off} = $${price}.`,['Correct sale price after subtracting the discount.','This is only the discount amount, not the price paid.','This adds the discount instead of subtracting it.','This is the original price with no discount applied.'],'Find the discount amount first, then subtract it from the original price.'))}

// Proportions
for(let i=1;i<=8;i++){const a=2+(i%4);let b=3+(i%5);if(b===a)b+=1;const k=6+i,given=a*k,neededB=k*b;
V9_TSI.push(O(`TSIA2-V20-M-PROP-${i}`,'Mathematics','Quantitative Reasoning — Proportions','Medium',`A mixture uses ${a} cups of ingredient A for every ${b} cups of ingredient B. If ${given} cups of A are used, how many cups of B are needed?`,[String(neededB),String(a*b),String(Math.max(1,neededB-b)),String(given)],0,`The ratio is ${a}:${b}. Since ${given} is ${k} times ${a}, use ${k} times ${b} cups of B: ${neededB}.`,['Correct — scales the ratio by the same factor.','Multiplies the two ratio numbers directly instead of scaling.','Subtracts instead of scaling the ratio.','Repeats the amount of A instead of finding B.'],'Find the scale factor between the given amount and the ratio, then apply it to the other ingredient.'))}

// Exponents
const expBases=[2,3,5,7];
for(let i=1;i<=8;i++){const b=expBases[i%4],e1=2+(i%4),e2=1+(i%3),sum=e1+e2;
V9_TSI.push(O(`TSIA2-V20-M-EXP-${i}`,'Mathematics','Algebraic Reasoning — Exponents',i%2?'Medium':'Easy',`Simplify ${b}^${e1} · ${b}^${e2}.`,[`${b}^${sum}`,`${b}^${sum+1}`,`${b*2}^${sum}`,`${b}^${Math.abs(e1-e2)||1}`],0,`When multiplying powers with the same base, add the exponents: ${b}^${e1}·${b}^${e2}=${b}^${e1+e2}.`,['Correct — exponents add for same-base multiplication.','Adds one extra to the exponent sum from a counting slip.','Changes the base instead of keeping it the same.','Subtracts the exponents instead of adding them.'],'Same base, multiplying powers: add the exponents.'))}

// Radicals
const sq=[16,25,36,49,64,81,100,121,144,169,196,225];
for(let i=0;i<8;i++){const v=sq[i],r=Math.sqrt(v);
V9_TSI.push(O(`TSIA2-V20-M-RAD-${i+1}`,'Mathematics','Algebraic Reasoning — Radicals','Easy',`What is √${v}?`,[String(r),String(r-1),String(r+1),String(Math.round(v/2))],0,`${r}×${r}=${v}, so √${v}=${r}.`,['Correct perfect-square root.','One less than the actual root.','One more than the actual root.','Half of the number under the radical, not its square root.'],'Find the integer that, when squared, equals the given number.'))}

// Linear Equations
for(let i=1;i<=12;i++){const a=2+(i%6),x=3+(i%9),bSign=i%2===0,bVal=2+(i%7),c=bSign?a*x+bVal:a*x-bVal;
V9_TSI.push(O(`TSIA2-V20-M-LEQ-${i}`,'Mathematics','Algebraic Reasoning — Linear Equations',i%4===0?'Easy':'Medium',`Solve for x: ${a}x ${bSign?'+':'−'} ${bVal} = ${c}.`,[String(x),String(x+1),String(x-1),String(c)],0,`${bSign?`Subtract ${bVal}`:`Add ${bVal}`} from both sides, then divide by ${a}: x=${x}.`,['Correct solution.','Off by one from an arithmetic slip.','Off by one from an arithmetic slip.','Mistakes the constant on the right side for x.'],'Undo addition/subtraction first, then divide to isolate x.'))}

// Systems of Equations
for(let i=1;i<=8;i++){const coef=2+(i%4),x=2+(i%6);let y=1+(i%5);if(y===x)y+=1;const s1=x+y,s2=coef*x-y;
V9_TSI.push(O(`TSIA2-V20-M-SYS-${i}`,'Mathematics','Algebraic Reasoning — Systems of Equations','Hard',`The system x + y = ${s1} and ${coef}x − y = ${s2} has solution (x,y). What is x?`,[String(x),String(y),String(s1),String(s2)],0,`Adding the two equations eliminates y: (${coef}+1)x=${s1+s2}, so x=${x}.`,['Correct — add the equations to eliminate y.','This is the value of y, not x.','This is x + y, not x alone.','This is the constant from the second equation, not the solution for x.'],'Add the two equations so that the y-terms cancel, then solve for x.'))}

// Functions
for(let i=1;i<=10;i++){const mag=2+(i%5),coef=i%2===0?mag:-mag,cmag=1+(i%6),b=i%3===0?-cmag:cmag,xv=2+(i%7),val=coef*xv+b;
V9_TSI.push(O(`TSIA2-V20-M-FUN-${i}`,'Mathematics','Algebraic Reasoning — Functions',i%2?'Medium':'Easy',`If f(x) = ${coef}x ${b>=0?'+ '+b:'− '+Math.abs(b)}, what is f(${xv})?`,[String(val),String(coef*xv),String(coef*(xv-1)+b),String(val+b)],0,`Substitute x=${xv}: ${coef}(${xv}) ${b>=0?'+':'−'} ${Math.abs(b)} = ${val}.`,['Correct substitution and evaluation.','Leaves out the constant term.','Substitutes the wrong x-value before evaluating.','Adds the constant twice.'],'Substitute the given value for x, then apply order of operations.'))}

// Slope
const slopeM=[1,-1,2,-2,3];
for(let i=1;i<=10;i++){const x1=1+(i%5),y1=2+(i%6),dx=2+(i%4),m=slopeM[i%5],dy=m*dx,x2=x1+dx,y2=y1+dy;
V9_TSI.push(O(`TSIA2-V20-M-SLP-${i}`,'Mathematics','Algebraic Reasoning — Slope','Medium',`A line passes through (${x1},${y1}) and (${x2},${y2}). What is its slope?`,[String(m),String(-m),String(m+1),String(dy)],0,`Slope = (y2−y1)/(x2−x1) = ${dy}/${dx} = ${m}.`,['Correct slope.','Reverses the sign of the slope.','Off by one from an arithmetic slip.','Reports the change in y only, without dividing by the change in x.'],'Divide the change in y by the change in x.'))}

// Factoring Quadratics
for(let i=1;i<=8;i++){const p=2+(i%5),q=3+((i+2)%6),B=p+q,C=p*q;
V9_TSI.push(O(`TSIA2-V20-M-FAC-${i}`,'Mathematics','Algebraic Reasoning — Factoring Quadratics','Hard',`Which expression is equivalent to x² − ${B}x + ${C}?`,[`(x − ${p})(x − ${q})`,`(x + ${p})(x + ${q})`,`(x − ${p+1})(x − ${Math.max(1,q-1)})`,`(x − ${B})(x − ${C})`],0,`Find two numbers that multiply to ${C} and add to ${B}: ${p} and ${q}.`,['Correct factor pair.','Uses the wrong signs for a minus-x, plus-constant trinomial.','This factor pair does not multiply to give the correct constant term.','Mistakes the coefficients themselves for the factors.'],'Look for two numbers whose product is the constant term and whose sum is the middle coefficient.'))}

// Linear Inequalities
for(let i=1;i<=8;i++){const a=2+(i%5),target=2+(i%9),b=2+(i%4),c=a*target+b;
V9_TSI.push(O(`TSIA2-V20-M-INEQ-${i}`,'Mathematics','Algebraic Reasoning — Linear Inequalities','Medium',`Which inequality is equivalent to ${a}x + ${b} < ${c}?`,[`x < ${target}`,`x > ${target}`,`x < ${target+1}`,`x < ${c}`],0,`Subtract ${b}, then divide by ${a} (positive, so the inequality direction stays the same): x < ${target}.`,['Correct — direction is preserved since we divided by a positive number.','Flips the inequality direction without a valid reason.','Off by one from an arithmetic slip.','Forgets to subtract the constant before dividing.'],'Isolate x the same way as an equation, and only flip the inequality when dividing by a negative.'))}

// Modeling with Expressions
for(let i=1;i<=8;i++){const fixed=200+i*50,costPer=3+(i%6),price=costPer+2+(i%5),margin=price-costPer;
V9_TSI.push(O(`TSIA2-V20-M-MOD-${i}`,'Mathematics','Algebraic Reasoning — Modeling with Expressions','Hard',`A business has fixed monthly costs of $${fixed} and pays $${costPer} per item produced. It sells each item for $${price}. Which expression represents monthly profit P if x items are sold?`,[`P = ${margin}x − ${fixed}`,`P = ${price}x − ${fixed}`,`P = ${margin}x + ${fixed}`,`P = ${fixed}x − ${margin}`],0,`Profit per item is $${price}−$${costPer}=$${margin}. Total profit is ${margin}x minus the fixed cost: P = ${margin}x − ${fixed}.`,['Correct — profit per item times x, minus fixed costs.','Forgets to subtract the per-item production cost.','Adds the fixed cost instead of subtracting it.','Swaps the roles of the fixed cost and the per-item profit.'],'Find profit per item first (price minus cost), then subtract the fixed cost from the total.'))}

// Area (triangle)
for(let i=1;i<=8;i++){const h=2*(2+(i%5)),b=3+i,area=b*(h/2);
V9_TSI.push(O(`TSIA2-V20-M-AREA-${i}`,'Mathematics','Geometric and Spatial Reasoning — Area','Medium',`A triangle has base ${b} units and height ${h} units. What is its area?`,[String(area),String(b*h),String(b+h),String(Math.round(area/2))],0,`Area = ½×base×height = ½×${b}×${h} = ${area}.`,['Correct area.','Forgets the ½ factor in the triangle area formula.','Adds the dimensions instead of using the area formula.','Applies the ½ factor a second time.'],'Use A = ½ × base × height for a triangle.'))}

// Circles
for(let i=1;i<=8;i++){const r=2+i,area=r*r;
V9_TSI.push(O(`TSIA2-V20-M-CIRC-${i}`,'Mathematics','Geometric and Spatial Reasoning — Circles','Medium',`A circle has radius ${r}. What is its area?`,[`${area}π`,`${2*r}π`,`${r}π`,`${2*area}π`],0,`Area = πr² = π(${r})² = ${area}π.`,['Correct area.','Uses 2r instead of r² (resembles circumference reasoning).','Forgets to square the radius.','Doubles the correctly-squared area.'],'Use A = πr², not the circumference formula.'))}

// Pythagorean Theorem
const triples=[[3,4,5],[6,8,10],[5,12,13],[9,12,15],[8,15,17],[7,24,25],[20,21,29],[12,16,20]];
triples.forEach(([a,b,c],idx)=>{
V9_TSI.push(O(`TSIA2-V20-M-PYT-${idx+1}`,'Mathematics','Geometric and Spatial Reasoning — Pythagorean Theorem','Medium',`A right triangle has legs ${a} and ${b}. What is the hypotenuse?`,[String(c),String(a+b),String(c-1),String(a*b)],0,`c=√(${a}²+${b}²)=√(${a*a}+${b*b})=√${a*a+b*b}=${c}.`,['Correct hypotenuse.','Adds the legs directly instead of using the Pythagorean theorem.','Off by one from an arithmetic slip.','Multiplies the legs, confusing this with the area of a rectangle.'],'Use c = √(a² + b²) for the hypotenuse of a right triangle.'))});

// Similarity
for(let i=1;i<=8;i++){const s1=2+i,mult=2+(i%3),s2=s1*mult,k=1+(i%4),given=k*s1,corresponding=k*s2;
V9_TSI.push(O(`TSIA2-V20-M-SIM-${i}`,'Mathematics','Geometric and Spatial Reasoning — Similarity','Medium',`Two similar figures have corresponding sides ${s1} and ${s2}. If another side of the smaller figure is ${given}, what is the corresponding side of the larger figure?`,[String(corresponding),String(corresponding+s1),String(Math.max(1,Math.round(given*s1/s2))),String(given)],0,`The scale factor is ${s2}/${s1}=${mult}. Multiply the given side by ${mult}: ${given}×${mult}=${corresponding}.`,['Correct — applies the scale factor.','Adds an extra side length instead of scaling proportionally.','Uses the inverse of the correct scale factor.','Repeats the smaller figure’s side without scaling.'],'Set up a proportion between corresponding sides and apply the scale factor consistently.'))}

// Translations
for(let i=1;i<=8;i++){const x=(i%2===0?i:-i),y=(i%3===0?-(i+1):(i+1)),dx=2+(i%5),dy=(i%2===0)?-(1+(i%4)):(1+(i%4));
V9_TSI.push(O(`TSIA2-V20-M-TRA-${i}`,'Mathematics','Geometric and Spatial Reasoning — Translations','Medium',`Point P(${x},${y}) is translated ${dx} units horizontally and ${dy} units vertically. What is P′?`,[`(${x+dx},${y+dy})`,`(${x-dx},${y-dy})`,`(${x+dx},${y})`,`(${x},${y+dy})`],0,`Add the horizontal shift to x and the vertical shift to y: (${x}+${dx}, ${y}+${dy}) = (${x+dx},${y+dy}).`,['Correct translated point.','Subtracts the shifts instead of adding them.','Applies only the horizontal shift and forgets the vertical one.','Applies only the vertical shift and forgets the horizontal one.'],'Add the horizontal shift to the x-coordinate and the vertical shift to the y-coordinate.'))}

// Probability (spinner, expected count)
for(let i=1;i<=10;i++){const n=4+(i%6);let t=1+(i%(n-1));if(t<2)t=2;const s=n*(2+(i%4)),favorable=n-t,expected=s*favorable/n;
V9_TSI.push(O(`TSIA2-V20-M-PROB-${i}`,'Mathematics','Probabilistic and Statistical Reasoning — Probability',i%2?'Medium':'Hard',`A fair ${n}-section spinner labeled 1 through ${n} is spun ${s} times. About how many spins are expected to show a number greater than ${t}?`,[String(expected),String(s*t),String(Math.round(expected/2)),String(s)],0,`${favorable} of the ${n} sections are greater than ${t}, so the expected count is ${s}×${favorable}/${n}=${expected}.`,['Correct expected count.','Multiplies spins by the threshold number instead of dividing by the number of sections.','Halves the expected count without justification.','Reports the total number of spins, not the expected favorable count.'],'Multiply the total number of trials by the probability of the favorable outcome.'))}

// Mean
for(let i=1;i<=8;i++){const base=5+i,vals=[base,base+2,base+4,base+6,base+8],sum=vals.reduce((a,b)=>a+b,0),mean=sum/5;
V9_TSI.push(O(`TSIA2-V20-M-MEAN-${i}`,'Mathematics','Probabilistic and Statistical Reasoning — Mean','Easy',`The data set is ${vals.join(', ')}. What is the mean?`,[String(mean),String(mean+2),String(mean-2),String(sum)],0,`Sum the values (${sum}) and divide by 5: ${sum}/5=${mean}.`,['Correct mean.','Off by one data-point interval from an arithmetic slip.','Off by one data-point interval from an arithmetic slip.','Reports the sum, forgetting to divide by the number of values.'],'Add all the values, then divide by how many values there are.'))}

// Median
for(let i=1;i<=8;i++){const base=3+i,vals=[base+5,base,base+8,base+2,base+1],sorted=[...vals].sort((a,b)=>a-b),median=sorted[2];
V9_TSI.push(O(`TSIA2-V20-M-MED-${i}`,'Mathematics','Probabilistic and Statistical Reasoning — Median','Easy',`The data set is ${vals.join(', ')}. What is the median?`,[String(median),String(sorted[0]),String(sorted[4]),String(Math.round(vals.reduce((a,b)=>a+b,0)/5))],0,`Order the values: ${sorted.join(', ')}. The middle value is ${median}.`,['Correct median.','Mistakes the minimum for the median.','Mistakes the maximum for the median.','Mistakes the mean for the median.'],'Order the values from least to greatest and take the middle one.'))}

// Safety net: nudge any accidental duplicate numeric distractor (never touches index 0, the correct answer)
V9_TSI.slice(v20StartIdx).forEach(q=>{
  const seen=new Set([q.choices[0]]);
  for(let i=1;i<4;i++){
    let val=q.choices[i];
    while(seen.has(val)){
      const n=parseFloat(val);
      val=(!isNaN(n) && String(n)===val)?String(n+1):val+'*';
    }
    q.choices[i]=val;seen.add(val);
  }
});

