/* ---------- V18: Adaptive-by-module SAT Practice Tests (Module 1 fixed, Module 2 routes on M1 accuracy) ---------- */
let v9Adaptive=null;
function v9AdaptiveStageConfig(stage){return [{section:'Reading & Writing',name:'R&W Module 1',count:7,duration:9*60,route:'mixed'},{section:'Reading & Writing',name:'R&W Module 2',count:7,duration:9*60,route:v9Adaptive?.rwRoute||'mixed'},{section:'Math',name:'Math Module 1',count:7,duration:10*60,route:'mixed'},{section:'Math',name:'Math Module 2',count:7,duration:10*60,route:v9Adaptive?.mathRoute||'mixed'}][stage]}
function v9LaunchAdaptiveStage(){const cfg=v9AdaptiveStageConfig(v9Adaptive.stage),pool=(cfg.section==='Math'?PRO_BANK.SAT.filter(q=>q.section==='Math'):PRO_BANK.SAT.filter(q=>q.section==='Reading & Writing')),set=adaptivePick(pool,cfg.count,cfg.route,v9Adaptive.used,'SAT',cfg.section);if(set.length<cfg.count){alert('This practice test module could not be built with enough unique questions.');v9Adaptive.active=false;return}cacheSet(satStore,set);saveSAT();satHideAll();$v3('satAdaptiveBreak')?.classList.remove('show');$v3('satPracticeShell').classList.add('show');satState={set,i:0,answers:{},confidence:{},flags:[],timed:true,start:Date.now(),seconds:cfg.duration,timerId:null,mode:`v9-sat-pt${v9Adaptive.num}-${v9Adaptive.stage+1}`,submitted:{},duration:cfg.duration,sessionCode:sessionCode('SAT')};$v3('satTestTitle').textContent=`SAT Practice Test ${v9Adaptive.num} — ${cfg.name}`;$v3('satModeLabel').textContent=`Adaptive Timed Practice • Module ${v9Adaptive.stage+1} of 4`;$v3('satConfidenceBox')?.classList.add('hidden');$v3('satSubmitBtn').classList.add('hidden');beginPacing('sat',satState,'satTimer',finishSAT,cfg.duration);renderSAT();location.hash='sat-center'}
const finishSATBeforeV18=finishSAT;
finishSAT=function(auto=false){
 if(v9Adaptive?.active){const cfg=v9AdaptiveStageConfig(v9Adaptive.stage),correct=satState.set.filter(q=>satState.answers[q.id]===q.a).length,total=satState.set.length,accuracy=pct(correct,total),elapsed=Math.max(0,satState.duration-satState.seconds),isFinal=v9Adaptive.stage===3;v9Adaptive.modules.push({set:satState.set,answers:{...satState.answers},flags:[...satState.flags]});cacheSet(satStore,satState.set);const thisModuleState=satState;if(isFinal){const priorModules=v9Adaptive.modules.slice(0,-1);let priorAnswered=0,priorCorrect=0;priorModules.forEach(m=>m.set.forEach(q=>{if(m.answers[q.id]!==undefined){priorAnswered++;if(m.answers[q.id]===q.a)priorCorrect++}}));satStore.answered-=priorAnswered;satStore.correct-=priorCorrect;const merged=mergeAdaptiveModules(v9Adaptive.modules),totalElapsed=v9Adaptive.results.reduce((n,x)=>n+x.elapsed,0)+elapsed;satState={...thisModuleState,set:merged.set,answers:merged.answers,flags:merged.flags,duration:totalElapsed,seconds:0,mode:`v9-sat-pt${v9Adaptive.num}-full`};cacheSet(satStore,satState.set)}finishSATBeforeV18(auto);if(!isFinal)satState=thisModuleState;v9Adaptive.results.push({name:cfg.name,section:cfg.section,correct,total,accuracy,elapsed,route:cfg.route});if(v9Adaptive.stage===0)v9Adaptive.rwRoute=accuracy>=60?'hard':'foundation';if(v9Adaptive.stage===2)v9Adaptive.mathRoute=accuracy>=60?'hard':'foundation';if(v9Adaptive.stage<3){v9Adaptive.stage++;$v3('satResults').classList.remove('show');$v3('satAdaptiveBreak').classList.add('show');const next=v9AdaptiveStageConfig(v9Adaptive.stage);$v3('satAdaptiveBreakTitle').textContent=`${cfg.name} complete`;$v3('satAdaptiveBreakText').innerHTML=`You answered <b>${correct} of ${total}</b> correctly (${accuracy}%). ${cfg.section==='Reading & Writing'&&v9Adaptive.stage===1?`Your Reading & Writing Module 2 will use the <span class="routePill">${routeLabel(accuracy)}</span>.`:cfg.section==='Math'&&v9Adaptive.stage===3?`Your Math Module 2 will use the <span class="routePill">${routeLabel(accuracy)}</span>.`:`Next: <b>${next.name}</b>.`}`;$v3('satAdaptiveBreakStats').innerHTML=`<div class="moduleBreakStat"><span>Accuracy</span><b>${accuracy}%</b></div><div class="moduleBreakStat"><span>Correct</span><b>${correct}/${total}</b></div><div class="moduleBreakStat"><span>Next</span><b>${next.name}</b></div>`;location.hash='sat-center';renderStudentHub();return}v9Adaptive.active=false;const all=v9Adaptive.results,tc=all.reduce((n,x)=>n+x.correct,0),tt=all.reduce((n,x)=>n+x.total,0);$v3('satResults').insertAdjacentHTML('afterbegin',`<div class="overallSummary" id="v9AdaptiveOverall"><h3>SAT Practice Test ${v9Adaptive.num} — Adaptive Module Summary</h3><div class="overallGrid"><div><span>Correct</span><b>${tc}/${tt}</b></div><div><span>Practice accuracy</span><b>${pct(tc,tt)}%</b></div><div><span>R&W route</span><b>${v9Adaptive.rwRoute==='hard'?'Higher-Difficulty':'Foundational'}</b></div><div><span>Math route</span><b>${v9Adaptive.mathRoute==='hard'?'Higher-Difficulty':'Foundational'}</b></div></div><p style="font-size:11px;color:#64748b;margin:10px 0 0">Practice performance only. This is not an official SAT score conversion. Module 2 difficulty was adjusted based on your Module 1 accuracy, mirroring how the real Digital SAT adapts. The full review and mistake list below cover all ${tt} questions across every module.</p></div>`);renderStudentHub();return}
 finishSATBeforeV18(auto)
};
function continueAdaptiveFlow(){if(v9Adaptive?.active)v9LaunchAdaptiveStage();else if(satAdaptive?.active)launchSATAdaptiveStage()}
$v3('satAdaptiveContinue')?.removeEventListener('click',launchSATAdaptiveStage);
$v3('satAdaptiveContinue')?.addEventListener('click',continueAdaptiveFlow);

