function v9Hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function v9Stable(pool,seed,count){return pool.slice().sort((a,b)=>v9Hash(a.id+'|'+seed)-v9Hash(b.id+'|'+seed)).slice(0,count)}
function v9Build(exam,num){const fresh=(arr,n)=>secureShuffle(arr).slice(0,n);if(exam==='SAT')return [...fresh(PRO_BANK.SAT.filter(q=>q.section==='Reading & Writing'),14),...fresh(PRO_BANK.SAT.filter(q=>q.section==='Math'),14)];if(exam==='ACT')return [...fresh(PRO_BANK.ACT.filter(q=>q.section==='English'),10),...fresh(PRO_BANK.ACT.filter(q=>q.section==='Math'),10),...fresh(PRO_BANK.ACT.filter(q=>q.section==='Reading'),6),...fresh(PRO_BANK.ACT.filter(q=>q.section==='Science (Optional)'),6)];return [...fresh(PRO_BANK.TSIA2.filter(q=>q.section==='Mathematics'),12),...fresh(PRO_BANK.TSIA2.filter(q=>q.section==='ELAR'),12)]}
